import sys
import io
from typing import List

# Define the function to solve the problem
def largeGroupPositions(s: str) -> List[List[int]]:
    """
    Finds the start and end indices of all large groups (3 or more consecutive
    identical characters) in a string.

    Args:
        s: The input string of lowercase letters.

    Returns:
        A list of lists, where each inner list [start, end] represents the interval
        of a large group, sorted by start index.
    """
    result = []
    n = len(s)
    # A large group requires at least 3 characters.
    # If the string is shorter than 3, no large groups are possible.
    if n < 3:
        return result

    start = 0  # Start index of the current potential group
    for i in range(n):
        # A group ends under two conditions:
        # 1. We are at the last character of the string (i == n - 1).
        # 2. The next character (s[i+1]) is different from the current one (s[i]).
        # This check marks the end of the current group at index `i`.
        if i == n - 1 or s[i] != s[i+1]:
            # Calculate the length of the group that just ended (from start to i, inclusive)
            length = i - start + 1
            # If the group's length is 3 or more, it's a large group.
            if length >= 3:
                # Add the [start, end] interval to the result list.
                result.append([start, i])
            # The next potential group starts at the index immediately following the current one.
            start = i + 1

    # The result list is naturally sorted by start index because we process the string
    # from left to right.
    return result

